async function api(path,options={}){const r=await fetch(path,{...options,headers:{...(options.body instanceof Blob?{}:{'Content-Type':'application/json'}),...options.headers}});let data;try{data=await r.json()}catch{throw Error('服务返回异常，请稍后重试。')}if(!r.ok){const e=Error(data.error||'请求未完成');e.status=r.status;e.code=data.code;throw e}return data}
