function workspace(){const p=current();if(!p)return `<div class="content">${pageHeading('还没有项目','创建第一个项目，开始设计共创。',`<button class="btn primary" data-action="new-project">新建项目</button>`)}</div>`;return `<div class="workspace-header"><div class="row between"><div><h1>${esc(p.name)}</h1><div class="meta"><span class="tag ${p.demo?'gray':'blue'}">${p.demo?'教学示例项目':'我的项目'}</span><span>工作稿 · ${p.versions.length?'V'+(p.versions.length+1):'V1'}</span><span class="save-status">已保存</span></div></div><div class="row"><button class="btn secondary small" data-action="save">${icon('check')}保存</button><button class="btn primary small" data-action="submit">提交预答辩 ${icon('arrow')}</button></div></div><div class="workspace-tools row"><button class="btn text small" data-action="collapse-materials">材料栏</button><button class="btn text small" data-action="collapse-feedback">点评栏</button><button class="btn text small" data-action="presentation">课堂展示</button><button class="btn text small" data-action="ai-design">辅助方案设计</button><button class="btn text small" data-action="saved-views">视图书签</button><button class="btn text small" data-action="components">模型构件</button></div><div class="mobile-pane-tabs"><button data-action="pane" data-value="materials" class="${pane==='materials'?'active':''}">材料</button><button data-action="pane" data-value="center" class="${pane==='center'?'active':''}">模型与汇报</button><button data-action="pane" data-value="feedback" class="${pane==='feedback'?'active':''}">点评与批注</button></div><div class="stagebar dw-model-stagebar">${DESIGN_STAGES.map(s=>`<a href="#/design/${p.id}/${s.id}"><span>${s.id}</span>${s.name}</a>`).join('')}</div></div><div class="workbench ${sessionStorage.getItem('studio-collapse-materials')==='1'?'collapse-materials':''} ${sessionStorage.getItem('studio-collapse-feedback')==='1'?'collapse-feedback':''}" data-pane="${pane}" style="--materials-width:${Math.min(380,Math.max(180,Number(localStorage.getItem('studio-material-width'))||220))}px;--feedback-width:${Math.min(480,Math.max(240,Number(localStorage.getItem('studio-feedback-width'))||320))}px"><aside class="materials"><div class="panel-title">项目材料<button data-action="project-details" title="编辑项目背景">${icon('edit')}</button></div><div class="file-group-title">${p.demo?'教学示例':'模型与图纸'}</div>${p.demo?`<button class="file-item ${selectedFile==='example'?'selected':''}" data-action="select-file" data-id="example">${icon('cube')}<span><span class="file-name">阅读亭 · 示例模型</span><small>交互示例 · 非 SKP 转换结果</small></span></button>`:''}${materialList(p.files,selectedFile)}<button class="upload-drop" data-action="upload" style="width:calc(100% - 4px)">${icon('upload')}拖入文件，或点击上传<small>SKP / PDF / JPG / PNG<br>当前单文件上限 20 MB</small></button><input id="file-input" type="file" accept=".skp,.pdf,.jpg,.jpeg,.png" hidden><div class="file-group-title">文字与过程</div><button class="file-item ${tab==='report'?'selected':''}" data-action="tab" data-value="report">${icon('file')}<span><span class="file-name">个人汇报稿</span><small>文字、依据与改写理由</small></span></button><button class="file-item" data-action="go-archive">${icon('history')}<span><span class="file-name">阶段版本</span><small>${p.versions.length} 个已保存快照</small></span></button><div class="file-group-title">课程关注点</div><p style="padding:0 8px;font-size:10px;line-height:1.9;color:#95a08b">${esc(state.course.focus)}</p></aside><div class="panel-resizer left" role="separator" tabindex="0" aria-label="调整材料栏宽度" aria-orientation="vertical" data-resizer="materials"></div><section class="work-center"><div class="center-tabs"><button data-action="tab" data-value="model" class="${tab==='model'?'active':''}">${icon('cube')}模型与图纸</button><button data-action="tab" data-value="report" class="${tab==='report'?'active':''}">${icon('edit')}汇报共创</button></div>${tab==='report'?editor(p):modelContent(p)}</section><div class="panel-resizer right" role="separator" tabindex="0" aria-label="调整点评栏宽度" aria-orientation="vertical" data-resizer="feedback"></div><aside class="feedback-panel"><div class="feedback-tabs"><button data-action="feedback-source" data-value="ai" class="${feedbackSource==='ai'?'active':''}">AI 点评 <small>${p.feedback.length}</small></button><button data-action="feedback-source" data-value="teacher" class="${feedbackSource==='teacher'?'active':''}">教师批注 <small>${p.annotations.length}</small></button></div>${feedbackSource==='ai'?`<div style="font-size:10px;color:#9b957e;line-height:1.8"><span data-ai-status>${esc(aiStatusText())}</span>${p.demo?' · 教学示例点评保留来源标记。':''}</div>${reviewFilters()}${filteredFeedback(p).map(f=>feedbackCard(f,p)).join('')||'<div class="empty">暂无符合条件的点评</div>'}<button class="btn secondary small" style="width:100%" data-action="ai-review">${icon('spark')}发起 AI 点评</button>`:teacherAnnotations(p)}</aside></div>`}
function modelContent(p){if(selectedFile==='example'&&p.demo)return `<div class="model-area" id="model-area"><div class="model-label">教学示例模型 V1 · 与上传文件无关联</div><div class="view-controls">${['轴测','俯视','正视','侧视'].map(v=>`<button data-action="camera" data-value="${v}">${v}</button>`).join('')}</div><div class="model-hint">左键旋转 · 右键平移 · 滚轮缩放<br>模型与批注仅用于体验共创流程</div><div class="bottom-controls"><button data-action="annotate" title="添加定位批注">${icon('pin')}</button><button data-action="camera" data-value="轴测" title="适应窗口／复位">${icon('reset')}</button><button data-action="fullscreen" title="全屏模型">${icon('expand')}</button></div></div><div class="model-footer"><span>阅读亭 / 概念体块示例</span><span class="row">${icon('cube')}交互三维视图</span></div>`;const f=p.files.find(f=>f.id===selectedFile);if(!f)return `<div class="blocked"><div class="big-icon">${icon('upload')}</div><h3>从你的设计材料开始</h3><p>上传 SketchUp 原文件、图纸或设计说明。原文件会保存至云端。SKP 将在本页后台转换为可交互的三维模型。</p><button class="btn primary" data-action="upload">${icon('upload')}上传设计材料</button></div>`;if(f.type==='skp')return modelMarkup(f,conversions.states.get(f.id),conversions.tasks.has(f.id));return `<div class="material-preview">${f.type==='pdf'?`<iframe src="/api/files/${f.id}?preview=1" title="${esc(f.name)}"></iframe>`:`<img src="/api/files/${f.id}?preview=1" alt="${esc(f.name)}">`}</div><div class="model-footer"><span>${esc(f.name)}</span>${f.type==='pdf'?`<button class="btn text" data-action="pdf-pages" data-id="${f.id}">选择关键页供 AI 使用</button>`:''}<a href="/api/files/${f.id}" download>下载原文件</a></div>`}
function editor(p){return `<div class="editor"><div class="row between" style="margin-bottom:20px"><div><h2>用自己的语言，讲述设计。</h2><p class="intro" style="margin:0">把设计选择、材料依据和未解决的问题写清楚。</p></div><button class="btn secondary small" data-action="ai-draft">${icon('spark')}AI 起稿</button></div><div class="editor-split"><aside class="draft-reference"><h3>${p.aiDraft?'AI 初稿 · '+esc(p.aiDraft.source):p.demo?'示例提纲 · 非 AI 实时生成':'汇报结构参考'}</h3>${esc(p.draft||'1. 问题与目标\n2. 设计策略\n3. 空间与流线\n4. 重点节点\n5. 总结与待验证问题').replace(/\n/g,'<br>')}<p style="margin-top:18px;color:#a39578;font-size:10px">${p.aiDraft?'依据与生成时间可在生成记录中查看。':'参考提纲不代表AI已读取你的模型；可连接 DeepSeek 生成真实初稿。'}</p>${p.aiDraft?'<button class="btn secondary small" data-action="use-ai-draft">加入个人稿后改写</button>':''}<button class="btn text" data-action="ai-history">生成记录 →</button></aside><div><div class="editor-block"><label for="report">个人汇报稿</label><textarea id="report" data-field="report" style="min-height:330px" placeholder="从问题与目标开始，写下你的设计思考…">${esc(p.report)}</textarea></div></div></div><div class="editor-block"><label for="reason">我为什么这样设计 / 这次为什么改写</label><textarea class="reason" id="reason" data-field="reason" placeholder="解释关键选择、取舍和修改带来的变化…">${esc(p.reason)}</textarea></div><div class="editor-block"><label for="evidence">依据在哪</label><textarea class="reason" id="evidence" data-field="evidence" placeholder="注明材料名称、版本与图纸位置；没有依据的判断请标为待验证。">${esc(p.evidence)}</textarea></div><div class="editor-actions"><span class="save-status" style="font-size:11px"></span><button class="btn primary small" data-action="save">${icon('check')}保存汇报</button></div></div>`}
function reviewFilters(){return `<div class="filter-row"><select id="review-status" aria-label="按状态筛选"><option value="all">全部状态</option>${['待回应','已回应','待复核','已解决','不同判断'].map(s=>`<option ${reviewStatus===s?'selected':''}>${s}</option>`).join('')}</select><select id="review-priority" aria-label="按优先级筛选"><option value="all">全部优先级</option>${['优先处理','进一步完善','可选优化'].map((s,i)=>`<option value="${i}" ${reviewPriority===String(i)?'selected':''}>${s}</option>`).join('')}</select></div>`}
function filteredFeedback(p){return p.feedback.filter(f=>(reviewStatus==='all'||(reviewStatus==='不同判断'?f.response&&f.response.decision!=='采纳':f.status===reviewStatus))&&(reviewPriority==='all'||f.priority===Number(reviewPriority)))}
function feedbackCard(f,p){return `<article class="feedback-card"><div class="row between"><span class="tag ${f.priority===0?'gold':f.priority===1?'blue':'gray'}">${['优先处理','进一步完善','可选优化'][f.priority]}</span><span style="font-size:9px;color:#9ca28f">${esc(f.status)}</span></div><h3>${esc(f.title)}</h3><div class="row" style="font-size:9px;color:#8a9984;gap:8px"><span>${esc(f.dimension)}</span><span>·</span><span>${esc(f.kind)}</span></div><button class="location" data-action="locate-feedback" data-id="${f.id}" data-project="${p.id}">↗ ${esc(f.location)} · ${esc(f.version)}</button><p>“${esc(f.quote)}”</p><details><summary>查看依据、建议与思考问题</summary><p><b>依据</b>　${esc(f.evidence)}</p><p><b>待补充</b>　${esc(f.need)}</p><p><b>建议</b>　${esc(f.suggestion)}</p><p><b>思考问题</b>　${esc(f.question)}</p><p style="font-size:9px;margin-top:8px">来源：${esc(f.source)}</p></details>${f.sourceKind==='ai'?`<button class="btn text" data-action="ai-followup" data-id="${f.runId}" data-index="${f.id.slice(f.runId.length+1)}">围绕这条点评继续追问 →</button>`:''}${f.response?`<div class="response-summary"><b>${esc(f.response.decision)}</b> · ${esc(f.response.reason)}${f.history?.length?`<div style="margin-top:6px;color:#8a9782">保留 ${f.history.length} 次历史回应</div>`:''}</div>`:''}<button class="response-button" data-action="respond" data-id="${f.id}" data-project="${p.id}">${f.response?'编辑回应与处理状态':'回应这条点评'} ${icon('arrow')}</button></article>`}
function teacherAnnotations(p){return `<p style="font-size:10px;line-height:1.8;color:#9b957e;margin-bottom:15px">教师视图演示 · 记录保存在当前私人空间。</p>${p.annotations.map((a,i)=>`<article class="feedback-card"><span class="tag gold">教师批注 · ${esc(a.modelVersion)}</span><h3>${esc(a.text)}</h3><p>${timestamp(a.at)}</p><button class="response-button" data-action="locate-annotation" data-id="${a.id}">恢复批注视角 ${icon('pin')}</button></article>`).join('')||'<div class="empty">暂时没有批注<br>可在已加载的真实模型或示例模型上添加问题点</div>'}<button class="btn secondary small" style="width:100%" data-action="annotate">${icon('pin')}在模型上批注</button>`}
function reviews(){const p=current();return `${pageHeading('让反馈，成为下一步。','找到依据缺口，说明自己的判断，让每一条意见得到回应。',projectSelect())}<div class="notice blue"><span data-ai-status>${esc(aiStatusText())}</span> · 点评依据仅限本次选择的材料；示例内容保留来源标记。<button class="btn text" data-action="ai-history">查看生成记录 →</button></div>${p?`<div class="row between"><h2 style="font-size:17px">${esc(p.name)}</h2><button class="btn secondary small" data-action="ai-review">${icon('spark')}发起 AI 点评</button></div>${reviewFilters()}<div class="review-grid">${filteredFeedback(p).map(f=>feedbackCard(f,p)).join('')||'<div class="empty">暂无点评。你可以先在共创工作台完善材料与汇报。</div>'}</div>`:''}`}
function defense(){const p=current();if(!p)return '<div class="empty">请先创建项目</div>';const latest=[...p.versions].reverse().find(v=>v.kind==='defense');return `${pageHeading('把设计讲清楚，把问题问深入。','教师围绕提交版本提问，学生用作品证据回应。',projectSelect())}<div class="notice blue">下方课堂记录为个人记录。跨账号师生讨论请使用“师生评审室”，共享选定快照并邀请教师。<button class="btn text" data-action="room-create">创建评审室 →</button></div><div class="row between" style="margin-bottom:22px"><div><h2 style="font-size:19px">${esc(p.name)}</h2><p class="muted" style="font-size:11px;margin-top:8px">${latest?'正在审阅 V'+latest.number+' · '+timestamp(latest.createdAt):'尚未提交预答辩快照'}</p></div><button class="btn primary" data-action="${latest?'new-question':'submit'}">${icon(latest?'plus':'upload')}${latest?'添加答辩问题':'提交预答辩'}</button></div><div class="defense-grid"><section><div class="section-heading"><h2>课堂问题与回答</h2>${latest?`<button data-action="view-version" data-id="${latest.id}">查看提交快照 ${icon('arrow')}</button>`:''}</div>${p.questions.map(q=>`<article class="question-card"><div class="row between"><span class="tag gold">教师问题 · V${q.versionNumber}</span><span class="tag gray">${esc(q.status||'待讨论')}</span></div><h3>${esc(q.text)}</h3><p>定位：${esc(q.location||'汇报与设计材料')}</p>${q.answer?`<div class="question-detail"><b>学生回答</b><br>${esc(q.answer)}</div>`:''}${q.feedback?`<div class="question-detail"><b>教师反馈</b><br>${esc(q.feedback)}</div>`:''}${q.task?`<p style="margin-top:12px">修改任务：${esc(q.task)}</p>`:''}<button class="btn text" style="margin-top:13px" data-action="edit-question" data-id="${q.id}">记录回答与反馈 ${icon('edit')}</button></article>`).join('')||'<div class="empty">从“为什么”开始一次对话。<br>提交快照后，可添加课堂问题和修改任务。</div>'}</section><section><div class="panel"><h2 style="font-size:17px;margin-bottom:19px">课前准备</h2><div class="callout">关注学生如何解释设计、使用证据和回应不同意见。空泛表述意味着需要追问，不能据此推断作者身份。</div><div class="task-item"><strong>01 / 查看个人改写</strong><br>对照设计依据和改写理由，找到值得继续讨论的选择。</div><div class="task-item"><strong>02 / 查看未回应问题</strong><br>当前项目有 ${pending(p)} 条点评待回应。<button class="btn text" data-action="go-reviews">前往点评区 →</button></div><div class="task-item"><strong>03 / 准备候选追问</strong><br>为什么在这里设置入口？<br>另一种布局为什么被放弃？<br>这个判断对应哪张图纸？</div><button class="btn secondary" style="margin-top:20px;width:100%" data-action="open-project" data-id="${p.id}">${icon('cube')}打开模型与设计材料</button></div><p class="copyright">课堂记录以文字为主，不进行语音或视频录制。</p></section></div>`}
function archive(){const p=current();if(!p)return '<div class="empty">请先创建项目</div>';return `${pageHeading('看见设计，如何一步步发生。','保留每一次选择、回应与修改，回到当时的作品和思考。',projectSelect())}<div class="row between" style="margin-bottom:25px"><h2 style="font-size:18px">${esc(p.name)}</h2><div class="row"><button class="btn secondary small" data-action="room-create">邀请评审</button><button class="btn secondary small" data-action="model-compare">模型对照</button><button class="btn secondary small" data-action="compare">${icon('compare')}对照版本</button><button class="btn primary small" data-action="snapshot">${icon('plus')}保存阶段版本</button></div></div><div class="panel" style="margin-bottom:28px"><div class="editor-block" style="margin:0"><label for="reflection">我的复盘：改了什么，为什么改，还有什么待验证？</label><textarea id="reflection" data-field="reflection" style="width:100%;min-height:100px;border:1px solid #dce2d4;background:#fffef9;padding:13px;border-radius:5px;font:inherit;line-height:1.9" placeholder="记录具体变化、材料依据与未解决的问题…">${esc(p.reflection)}</textarea><div class="row between" style="margin-top:14px"><span class="save-status" style="font-size:11px"></span><button class="btn secondary small" data-action="save">保存复盘</button></div></div></div>${[...p.versions].reverse().map(v=>`<article class="timeline-item"><div class="timeline-date">${date(v.createdAt)}<br><small>${new Date(v.createdAt).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false})}</small></div><div class="timeline-card"><div class="row between"><h3>V${v.number} · ${esc(v.label)}</h3><span class="tag ${v.kind==='defense'?'gold':'blue'}">${v.kind==='defense'?'预答辩提交':'阶段快照'}</span></div><p>${esc(v.note||'保存当前材料、汇报、回应与课堂记录。')}</p><div class="row between"><span class="muted" style="font-size:10px">${v.snapshot.files.length} 份材料 · ${v.snapshot.feedback.length} 条点评 · 内容已锁定</span><div class="row"><button class="btn text" data-action="view-version" data-id="${v.id}">查看</button><button class="btn text" data-action="report-html" data-id="${v.id}">${icon('download')}图文报告</button><button class="btn text" data-action="export-version" data-id="${v.id}">文字档案</button></div></div></div></article>`).join('')||'<div class="empty">这里将保存你的设计过程。<br>点击“保存阶段版本”，创建第一个不可变快照。</div>'}`}
function course(){return `${pageHeading('共同的任务，不同的设计回答。','明确设计背景与讨论重点，让每一轮共创都有方向。')}<div class="course-grid"><section class="panel"><h2>课程任务</h2><form id="course-form"><div class="form-field"><label for="course-name">课程名称</label><input id="course-name" name="name" value="${esc(state.course.name)}" required maxlength="100"></div><div class="form-field"><label for="course-brief">任务背景与要求</label><textarea id="course-brief" name="brief" rows="5" required>${esc(state.course.brief)}</textarea></div><div class="form-field"><label for="course-focus">教师关注点</label><textarea id="course-focus" name="focus" rows="4" required>${esc(state.course.focus)}</textarea><small>关注点将在共创工作台的材料侧栏展示。</small></div><button class="btn primary" type="submit">${icon('check')}保存课程任务</button></form></section><section><div class="panel"><h2>工作坊服务</h2><div class="service-row"><div><h3>项目与文件存储</h3><p>私人空间中的材料、文字与阶段档案</p></div><span class="tag">云端存储</span></div><div class="service-row"><div><h3>SketchUp 原生模型解析</h3><p>原文件上传后自动转换，保留组件与基础材质</p></div><span class="tag">已启用</span></div><div class="service-row"><div><h3>DeepSeek 起稿与点评</h3><p data-ai-status>${esc(aiStatusText())}</p></div><button class="btn secondary small" data-action="ai-connect">服务状态</button></div><div class="service-row"><div><h3>师生评审室</h3><p>版本授权、教师提问、学生回应与复核</p></div><a class="btn text" href="#/collaboration">进入评审室 →</a></div><button class="btn text" style="margin-top:18px" data-action="services">查看功能与边界 ${icon('arrow')}</button></div><p class="copyright">网站公开展示；项目按登录账号独立保存。</p></section></div>`}
function showModal(title,desc,body,wide=false){viewTools.disposeCompare();if(!body.includes('id="pdf-picker"'))materials.closePdf();modalFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="modal-close" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div>${desc?`<p class="modal-description">${desc}</p>`:''}${body}</section></div>`;setTimeout(()=>$('.modal input,.modal textarea,.modal button')?.focus(),30);}
function closeModal(){ materials.closePdf();viewTools.disposeCompare();$('#modal-root').innerHTML='';modalFocus?.focus?.();}
function newProjectModal(){showModal('让一个新想法，开始生长。','填写项目背景，接着上传模型与图纸。',`<form id="new-project-form"><div class="form-field"><label>项目名称</label><input name="name" required maxlength="80" placeholder="例如：林间共读 · 社区阅读亭"></div><div class="form-field"><label>任务背景与场地条件</label><textarea name="description" required placeholder="项目位于哪里，需要回应什么问题？"></textarea></div><div class="form-field"><label>设计目标</label><textarea name="goal" placeholder="希望通过设计实现什么？"></textarea></div><div class="form-field"><label>目标使用者</label><input name="users" placeholder="例如：学生、社区居民、步行者"></div><div class="modal-actions"><button type="button" class="btn secondary" data-action="close-modal">取消</button><button class="btn primary" type="submit">创建项目 ${icon('arrow')}</button></div></form>`)}
function responseModal(f,p){showModal('回应点评，说明你的判断。',esc(f.title),`<form id="response-form" data-id="${f.id}" data-project="${p.id}"><div class="form-field"><label>我的处理决定</label><div class="choice-group">${['采纳','部分采纳','不采纳'].map((s,i)=>`<label><input type="radio" name="decision" value="${s}" ${f.response?.decision===s||(!f.response&&i===0)?'checked':''}>${s}</label>`).join('')}</div></div><div class="form-field"><label>理由与依据 <span class="muted">（必填）</span></label><textarea name="reason" required placeholder="无论是否采纳，请解释判断依据。">${esc(f.response?.reason||'')}</textarea></div><div class="form-field"><label>关联的修改</label><textarea name="change" placeholder="修改了哪个段落、哪份材料？">${esc(f.response?.change||'')}</textarea></div><div class="form-field"><label>处理状态</label><select name="status">${['已回应','待复核','已解决','待回应'].map(s=>`<option ${(f.response?f.status:'已回应')===s?'selected':''}>${s}</option>`).join('')}</select><small>可重新打开为“待回应”；编辑回应将保留历史记录。</small></div>${f.history?.length?`<details><summary style="font-size:11px;color:#8c9981;cursor:pointer">查看 ${f.history.length} 条历史回应</summary>${f.history.map(h=>`<p style="font-size:11px;line-height:1.9;margin-top:10px">${timestamp(h.at)} · ${esc(h.decision)}<br>${esc(h.reason)}</p>`).join('')}</details>`:''}<div class="modal-actions"><button type="button" class="btn secondary" data-action="close-modal">取消</button><button class="btn primary" type="submit">保存回应</button></div></form>`)}
function snapshotModal(kind){const p=current();if(!p)return;if(kind==='defense'&&!p.report.trim()){toast('请先填写个人汇报稿，再提交预答辩。');tab='report';goWorkspace();return}showModal(kind==='defense'?'提交一个明确的设计版本。':'保存这一步的设计思考。','将当前材料、文字和讨论保存为独立快照。后续修改不会改变这个版本。',`<form id="snapshot-form" data-kind="${kind}"><div class="form-field"><label>版本标题</label><input name="label" required maxlength="100" value="${kind==='defense'?'预答辩提交稿':stages[p.stage]+' · 阶段归档'}"></div><div class="form-field"><label>修改说明与待验证问题</label><textarea name="note" required placeholder="这一版改了什么？依据是什么？还有什么待验证？">${esc(p.reflection||'')}</textarea></div><div class="callout">${p.files.length} 份材料 · ${p.feedback.filter(f=>f.status!=='已解决').length} 条未解决点评${p.files.some(f=>f.type==='skp'&&f.conversion?.status!=='ready')?' · 部分 SKP 尚未转换完成':''}</div><div class="modal-actions"><button class="btn secondary" type="button" data-action="close-modal">取消</button><button class="btn primary" type="submit">${kind==='defense'?'确认提交':'保存快照'}</button></div></form>`)}
function questionModal(q){const p=current();const v=[...p.versions].reverse().find(v=>v.kind==='defense');if(!v){toast('先提交预答辩快照，再记录课堂问题。');return}showModal(q?'记录回答与教师反馈':'从一个具体问题开始',`当前审阅 V${q?.versionNumber||v.number} · 教师视图演示`, `<form id="question-form" data-id="${q?.id||''}"><div class="form-field"><label>教师问题</label><textarea name="text" required>${esc(q?.text||'')}</textarea></div><div class="form-field"><label>材料 / 段落位置</label><input name="location" value="${esc(q?.location||'')}"></div><div class="form-field"><label>学生回答要点</label><textarea name="answer">${esc(q?.answer||'')}</textarea></div><div class="form-field"><label>教师反馈</label><textarea name="feedback">${esc(q?.feedback||'')}</textarea></div><div class="form-field"><label>后续修改任务</label><input name="task" value="${esc(q?.task||'')}"></div><div class="form-field"><label>状态</label><select name="status">${['待讨论','继续修改','待复核','已完成'].map(s=>`<option ${q?.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="modal-actions"><button type="button" class="btn secondary" data-action="close-modal">取消</button><button type="submit" class="btn primary">保存课堂记录</button></div></form>`)}
function versionText(v){const s=v.snapshot;return `${s.name}\nV${v.number} · ${v.label}\n保存时间：${timestamp(v.createdAt)}\n\n修改说明\n${v.note}\n\n任务背景\n${s.description}\n\n设计目标\n${s.goal||'未填写'}\n\n目标使用者\n${s.users||'未填写'}\n\n个人汇报稿\n${s.report||'未填写'}\n\nAI 初稿参考\n${s.aiDraft? s.aiDraft.source+' / '+timestamp(s.aiDraft.createdAt):'结构参考或教学示例'}\n${s.draft||'未生成'}\n\n候选追问\n${s.aiDraft?.questions?.join('\n')||'未生成'}\n\n改写理由\n${s.reason||'未填写'}\n\n材料依据\n${s.evidence||'未填写'}\n\n材料清单\n${s.files.map(f=>`${f.name} · 文件版本 ${f.id} · ${f.type==='skp'?(MODEL_STATUS[f.conversion?.status]||'原文件已保存')+(f.conversion?.resultId?' · 转换版本 '+f.conversion.resultId:''):'已上传'}`).join('\n')||'暂无上传材料'}\n\n点评与回应\n${s.feedback.map(f=>`[${f.source}] ${f.title}（${f.status}）\n位置：${f.location} · ${f.version}\n维度：${f.dimension} · 优先级：${['优先处理','进一步完善','可选优化'][f.priority]} · ${f.kind}\n原文：${f.quote}\n依据：${f.evidence}\n待补充：${f.need}\n建议：${f.suggestion}\n思考问题：${f.question}\n回应：${f.response?f.response.decision+' / '+f.response.reason:'待回应'}\n关联修改：${f.response?.change||'未填写'}\n回应历史：${(f.history||[]).map(h=>timestamp(h.at)+' / '+h.decision+' / '+h.reason+' / '+(h.change||'')).join('；')||'无'}`).join('\n\n')||'暂无点评'}\n\n课堂记录\n${s.questions.map(q=>`V${q.versionNumber} 教师问题：${q.text}\n学生回答：${q.answer}\n教师反馈：${q.feedback}\n后续任务：${q.task}\n处理状态：${q.status}\n课堂历史：${(q.history||[]).map(h=>JSON.stringify(h)).join('；')||'无'}`).join('\n\n')||'暂无课堂记录'}\n\n模型批注\n${s.annotations.map(a=>`${a.text} · ${a.modelVersion} · ${timestamp(a.at)}\n位置：${JSON.stringify(a.position)}\n相机：${JSON.stringify(a.camera)}`).join('\n')||'暂无批注'}\n\n复盘与待验证问题\n${s.reflection||'未填写'}\n\n六阶段设计共创\n${workflowText(s)||'此版本尚无六阶段记录'}\n\n功能说明\n教学示例不代表真实 AI 判断或用户 SKP 解析结果。SKP 使用 OpenSKP 转换，特殊样式和可见性仍需对照原模型。真实AI内容标明服务与模型；教学示例继续保留来源。师生评审室提供选定快照的跨账号授权；后续讨论独立保存。\n`}
function viewVersion(v){showModal(`V${v.number} · ${esc(v.label)}`,'不可变阶段快照 · 之后的编辑不会改写这里的内容。',`<pre class="snapshot-report">${esc(versionText(v))}</pre><div class="modal-actions"><button class="btn primary" data-action="report-html" data-id="${v.id}">${icon('download')}图文报告</button><button class="btn text" data-action="export-version" data-id="${v.id}">文字档案此版本</button></div>`,true)}
function compareModal(){const vs=current().versions;if(vs.length<2){toast('至少保存两个阶段版本后，即可并排对照。');return}showModal('对照版本，看见设计的变化。','并排查看所选版本的汇报、回应与复盘。',`<div class="diff-cols">${[vs.length-2,vs.length-1].map((n,i)=>`<section><select class="snapshot-select compare-select" data-side="${i}">${vs.map((v,j)=>`<option value="${v.id}" ${j===n?'selected':''}>V${v.number} · ${esc(v.label)}</option>`).join('')}</select><pre id="compare-${i}">${esc(versionText(vs[n]))}</pre></section>`).join('')}</div>`,true)}
function guide(){showModal('共创，从一个真实问题开始。','学生负责解释选择，AI 辅助整理与追问，教师主持讨论与评价。',`<div class="guide-list">${[...DESIGN_STAGES.map(stage=>['0'+stage.id+' / '+stage.name,stage.purpose]),['多元参与与设计生成','在每个阶段组织材料、保存设计决定、邀请多方讨论。AI 生成文字策略与候选建议，先审阅再纳入候选区；采用时说明理由。概念图与三维模型生成仍需另接相应服务。'],['真实评审与来源','个人自记与转录反馈保留来源标识。保存阶段版本后，邀请教师、同伴或使用者用真实账号提问、回应并复核；模拟 AI 视角不代表真人意见。'],['模型、图纸与版本','上传 SKP 自动转换，PDF 可选页转图，模型支持视图书签与定位批注。六阶段记录随阶段快照保存，可导出共创报告。']].map(([h,p])=>`<article><h3>${h}</h3><p>${p}</p></article>`).join('')}</div><div class="modal-actions"><button class="btn primary" data-action="close-modal">开始共创 ${icon('arrow')}</button></div>`,true)}
function services(){showModal('当前可用功能与服务边界','课程试用版 · 云端私人工作空间',`<div class="guide-list"><article><h3>已实现的工作流程</h3><p>六阶段设计共创、任务与调研记录、场地底图标注、面积与约束核查、多方案比较、阶段 AI 候选、讨论回应、图纸模型查看、真实多方评审、版本对照与导出。</p></article><article><h3>SKP 转换 · 已启用</h3><p>使用 MIT 许可的 OpenSKP 1.5.0，把真实 SKP 转为包含网格、组件变换、基础材质和嵌入贴图的 GLB。原文件与结果保存至云端；转换在本页后台进行，关闭页面会中断。支持取消、超时提示与失败重试。原文件上限 20 MB，输出上限 32 MB，模型兼容性以实际解析为准。样本验证覆盖版本头 13、17、20、25；图层可见性、文字标注和特殊样式需对照原模型检查。</p></article><article><h3>DeepSeek AI 起稿与点评</h3><p><span data-ai-status>${esc(aiStatusText())}</span>。网站统一提供 AI 服务，管理员启用后，注册用户无需个人 API Key。每次明确选择材料后生成；结果先审阅，再保存到初稿参考区或点评列表。旧记录和学生回应继续保留。图片与模型视图是否可读，以所选模型的能力为准；PDF 可选择关键页保存为图片，再交给支持视觉的模型读取；未选页的 PDF 仍只列出文件名。</p></article><article><h3>师生评审室 · 版本授权</h3><p>项目所有者共享选定快照并生成邀请。评审教师邀请绑定邮箱，可提问、布置修改任务和复核；所有者回应；访客只读。邀请可设期限并随时撤销。角色由后端授权决定。机构教师身份与全班名册尚未接入。</p></article><article><h3>保存与版本</h3><p>记录与原文件保存在云端。网络失败会显示保存错误；版本冲突时请先复制未保存内容，再刷新读取最新状态。阶段快照不会随工作稿修改。</p></article></div>`,true)}
function goWorkspace(){location.hash='#/workspace/'+current().id;if(route==='workspace')render()}
async function setupViewer(){const container=$('#model-area'),p=current(),file=p.files.find(f=>f.id===selectedFile),model=file?conversions.states.get(file.id):null;const isDemo=!file&&p.demo&&selectedFile==='example';if(!container||(!isDemo&&model?.status!=='ready'))return;const binding=isDemo?{modelVersion:'示例模型 V1',fileId:null,modelResultId:null}:{modelVersion:file.name+' · '+model.resultId.slice(0,8),fileId:file.id,modelResultId:model.resultId};const annotations=p.annotations.filter(a=>isDemo?!a.fileId:a.fileId===file.id&&a.modelResultId===model.resultId);try{const onPoint=point=>{showModal('给这个空间，留下一个问题。','批注将绑定 '+esc(binding.modelVersion)+' 的空间位置和相机。',`<form id="annotation-form"><div class="form-field"><label>问题 / 设计批注</label><textarea name="text" required placeholder="例如：这个入口为什么设置在这里？"></textarea></div><div class="modal-actions"><button class="btn secondary" type="button" data-action="close-modal">取消</button><button class="btn primary" type="submit">保存批注</button></div></form>`);$('#annotation-form')._point=point;$('#annotation-form')._binding=binding};const onSelect=id=>{const a=p.annotations.find(a=>a.id===id);if(a){viewer?.restore(a.camera);toast(a.text)}};let result;if(isDemo){const mod=await import('./viewer.js');if(!container.isConnected)return;result=mod.createViewer(container,p.art||0,annotations,onPoint,onSelect)}else{const mod=await import('./model-viewer.js');if(!container.isConnected)return;result=await mod.createModelViewer(container,model.viewerUrl,annotations,onPoint,onSelect)}if(!container.isConnected){result.dispose();return}viewer=result;disposeViewer=result.dispose;viewerBindingKey=p.id+'/'+(file?.id||'example')+'/'+(model?.resultId||'demo');const remembered=cameraMemory.get(viewerBindingKey);if(remembered)viewer.restore(remembered);container.querySelector('#model-load-state')?.remove();if(container._restoreView){viewer.setView(container._restoreView);delete container._restoreView}if(container._restoreCamera){viewer.restore(container._restoreCamera);delete container._restoreCamera}}catch(e){if(container.isConnected){const label=container.querySelector('#model-load-state');if(label){label.classList.add('error');label.textContent='转换结果已保存，但三维视图加载失败：'+e.message}else container.insertAdjacentHTML('afterbegin','<div class="notice">三维视图暂不可用：'+esc(e.message)+'</div>')}}}
function modelInfo(){const f=current().files.find(f=>f.id===selectedFile),m=f&&conversions.states.get(f.id);if(!m)return;const meta=m.metadata||{};showModal('SKP 转换记录',esc(f.name),`<div class="guide-list"><article><h3>真实模型 · 转换完成</h3><p>源文件版本：${esc(meta.sourceVersion)}<br>输出单位：米（Y 轴向上）<br>网格：${meta.meshes} · 节点：${meta.nodes} · 三角形：${meta.triangles}<br>材质：${meta.materials} · 嵌入贴图：${meta.textures}<br>转换时间：${timestamp(m.completedAt)}<br>转换结果编号：${esc(m.resultId)}</p></article><article><h3>已知范围与限制</h3><p>${esc((meta.warnings||[]).join(' '))}<br>样本验证覆盖版本头 13、17、20、25；不表示所有同年文件均可解析。原文件保留，批注不会自动迁移到新上传的模型。</p></article><article><h3>转换方式</h3><p>使用 OpenSKP 1.5.0，在浏览器独立后台进程中解析，再把 GLB 结果保存至本网站。不会将模型发送到额外的转换服务。</p></article></div>`)}

async function uploadFile(file){if(!file)return;if(file.size>20*1024*1024){toast('单个文件不能超过 20 MB。');return}if(!/\.(skp|pdf|png|jpe?g)$/i.test(file.name)){toast('请选择 SKP、PDF、PNG 或 JPG 文件。');return}if(file.size===0){toast('文件为空，请重新选择。');return}const target=current();const uploadButton=$('.upload-drop');if(uploadButton){uploadButton.disabled=true;uploadButton.innerHTML='正在上传原文件…<small>完成后会显示真实处理状态</small>'}try{const r=await api('/api/files?name='+encodeURIComponent(file.name)+'&project='+encodeURIComponent(target.id),{method:'POST',body:file});target.files.push(r.file);selectedFile=r.file.id;tab='model';changed();await save();render();toast(file.name+' 已上传'+(r.file.type==='skp'?'，开始转换。':'。'));if(r.file.type==='skp')conversions.start(r.file)}catch(e){toast('上传未完成：'+e.message);render()}}
function bindInputs(){document.querySelectorAll('[data-resizer]').forEach(el=>{const side=el.dataset.resizer,bench=el.closest('.workbench');const setWidth=x=>{const value=Math.max(side==='materials'?180:240,Math.min(side==='materials'?380:480,x));bench.style.setProperty('--'+side+'-width',value+'px');localStorage.setItem('studio-'+(side==='materials'?'material':'feedback')+'-width',value);el.setAttribute('aria-valuenow',value)};el.addEventListener('pointerdown',e=>{e.preventDefault();el.setPointerCapture(e.pointerId);const start=e.clientX,width=side==='materials'?bench.querySelector('.materials').getBoundingClientRect().width:bench.querySelector('.feedback-panel').getBoundingClientRect().width;const move=ev=>setWidth(width+(ev.clientX-start)*(side==='materials'?1:-1));el.addEventListener('pointermove',move);el.addEventListener('pointerup',()=>el.removeEventListener('pointermove',move),{once:true})});el.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const width=parseFloat(getComputedStyle(bench).getPropertyValue('--'+side+'-width'));setWidth(width+(e.key==='ArrowRight'?20:-20)*(side==='materials'?1:-1))})});document.querySelectorAll('[data-field]').forEach(el=>el.addEventListener('input',()=>{current()[el.dataset.field]=el.value;if(el.dataset.field==='report'&&el.value.trim())current().stage=Math.max(current().stage,2);changed()}));$('#project-search')?.addEventListener('input',e=>{search=e.target.value;const list=state.projects.filter(p=>(filter==='all'||(filter==='active'?p.stage<5:p.stage>=5))&&p.name.toLowerCase().includes(search.toLowerCase()));$('#project-results').innerHTML=list.map(projectCard).join('')||'<div class="empty">没有找到匹配的项目。</div>'});$('.view-role')?.addEventListener('change',e=>{role=e.target.value;sessionStorage.setItem('studio-role',role);render();toast('已切换演示视图；访问权限没有变化。')});$('.project-select')?.addEventListener('change',e=>{projectId=e.target.value;selectedFile=current().demo?'example':current().files[0]?.id||'';render()});$('#review-status')?.addEventListener('change',e=>{reviewStatus=e.target.value;render()});$('#review-priority')?.addEventListener('change',e=>{reviewPriority=e.target.value;render()});$('#file-input')?.addEventListener('change',e=>uploadFile(e.target.files[0]));const drop=$('.upload-drop');if(drop){drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('dragover')});drop.addEventListener('dragleave',()=>drop.classList.remove('dragover'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('dragover');uploadFile(e.dataTransfer.files[0])})}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,p=current(),id=b.dataset.id;try{if(a==='close-modal')closeModal();else if(a.startsWith('board-'))await board.action(a,b);else if(a.startsWith('sp-'))await planner.action(a,b);else if(a.startsWith('dw-'))await designFlow.action(a,b);else if(a.startsWith('room-'))await rooms.action(a,b);else if(a==='material-meta')materials.meta(id);else if(a==='pdf-pages')await materials.pages(id);else if(a==='pdf-preview')await materials.preview();else if(a==='saved-views')viewTools.open();else if(a==='save-view')await viewTools.saveView();else if(a==='restore-view')await viewTools.restore(id);else if(a==='delete-view')await viewTools.remove(id);else if(a==='components')viewTools.components();else if(a==='model-compare')viewTools.compare();else if(a==='report-html'){downloadReport(p.versions.find(v=>v.id===id));toast('报告已导出，可用浏览器打印为 PDF。')}else if(a==='ai-followup')await ai.followup(id,Number(b.dataset.index),b.dataset.parent||null);else if(a==='collapse-materials'||a==='collapse-feedback'){const key='studio-'+a;sessionStorage.setItem(key,sessionStorage.getItem(key)==='1'?'0':'1');render()}else if(a==='presentation'){sessionStorage.setItem('studio-presentation',sessionStorage.getItem('studio-presentation')==='1'?'0':'1');render()}else if(a==='menu')$('.sidebar').classList.toggle('open');else if(a==='new-project')newProjectModal();else if(a==='open-project'){projectId=id;selectedFile=current().demo?'example':current().files[0]?.id||'';tab='model';pane='center';location.hash='#/design/'+id;if(route==='design')render()}else if(a==='project-filter'){filter=b.dataset.value;render()}else if(a==='tab'){tab=b.dataset.value;pane='center';render()}else if(a==='pane'){pane=b.dataset.value;render()}else if(a==='feedback-source'){feedbackSource=b.dataset.value;render()}else if(a==='select-file'){selectedFile=id;tab='model';pane='center';render()}else if(a==='upload')$('#file-input')?.click();else if(a==='save'||a==='retry-save'){await save();toast('已保存至云端。');if(a==='retry-save')render()}else if(a==='stage'){const i=+b.dataset.value;if(!p){newProjectModal();return}if(i===5){location.hash='#/defense';return}if(i===6){location.hash='#/archive';return}if(i===3||i===4){location.hash='#/reviews';return}if(i===0){showProjectDetails();return}tab='report';pane='center';goWorkspace();if(i===1)ai.open('draft')}else if(a==='respond'){const target=state.projects.find(p=>p.id===b.dataset.project);responseModal(target.feedback.find(f=>f.id===id),target)}else if(a==='locate-feedback'){projectId=b.dataset.project;tab='report';pane='center';goWorkspace();const f=current().feedback.find(f=>f.id===id);if(f.materialFileId&&current().files.some(x=>x.id===f.materialFileId)){selectedFile=f.materialFileId;tab='model';if(f.materialVersionId){const m=conversions.states.get(selectedFile)||await conversions.inspect(selectedFile);if(m)conversions.states.set(selectedFile,{...m,status:'ready',resultId:f.materialVersionId,viewerUrl:'/api/models/'+selectedFile+'/results/'+f.materialVersionId})}render();const view=$('#model-area');if(view&&['轴测','俯视','正视','侧视'].includes(f.materialViewLabel))view._restoreView=f.materialViewLabel;return}setTimeout(()=>{const t=$('#report');if(!t)return;const start=t.value.indexOf(f.quote);t.focus();if(start>=0)t.setSelectionRange(start,start+f.quote.length);else toast('原文已被改写，请对照点评中的原始引文。')},100)}else if(a==='go-reviews')location.hash='#/reviews';else if(a==='go-archive')location.hash='#/archive';else if(a==='submit')snapshotModal('defense');else if(a==='snapshot')snapshotModal('stage');else if(a==='view-version')viewVersion(p.versions.find(v=>v.id===id));else if(a==='export-version'){const v=p.versions.find(v=>v.id===id);const blob=new Blob([versionText(v)],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=p.name+'-V'+v.number+'-共创记录.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出所选版本的完整记录。')}else if(a==='compare')compareModal();else if(a==='new-question')questionModal();else if(a==='edit-question')questionModal(p.questions.find(q=>q.id===id));else if(a==='guide')guide();else if(a==='services')services();else if(a==='project-details')showProjectDetails();else if(a==='notifications'){showModal('你的下一步','从待回应的问题开始，把设计向前推进。',`<div class="guide-list">${state.projects.map(p=>`<article><h3>${esc(p.name)}</h3><p>${pending(p)} 条待回应点评 · 当前阶段：${stages[p.stage]}</p><button class="btn text" data-action="open-project" data-id="${p.id}">继续共创 →</button></article>`).join('')}</div>`)}else if(a==='ai-design'){await ai.design(5)}else if(a==='ai-draft'||a==='ai-review'){await ai.open(a==='ai-draft'?'draft':'review')}else if(a==='ai-connect'){await ai.connection()}else if(a==='ai-personal-connect'){await ai.connection(true)}else if(a==='ai-history'){await ai.history()}else if(a==='ai-run'){await ai.loadRun(id)}else if(a==='ai-apply'){await ai.apply(id)}else if(a==='ai-disconnect'){await ai.disconnect()}else if(a==='use-ai-draft'){if(!p.aiDraft||!p.draft)return;if(p.report.includes(p.draft))return toast('这份初稿已加入个人稿。');p.report=p.report.trim()?p.report+'\n\n'+p.draft:p.draft;p.stage=Math.max(p.stage,2);changed();await save();render();toast('候选稿已加入，请用自己的语言核验和改写。')}else if(a==='retry-model'){const f=p.files.find(f=>f.id===id);if(f)conversions.start(f)}else if(a==='cancel-model'){await conversions.cancel(id)}else if(a==='refresh-model'){await conversions.inspect(id)}else if(a==='model-info'){modelInfo()}else if(a==='camera')viewer?.setView(b.dataset.value);else if(a==='fullscreen'){if(document.fullscreenElement)await document.exitFullscreen();else await $('#model-area')?.requestFullscreen()}else if(a==='annotate'){if(tab!=='model'||!viewer){toast('请等待三维模型加载完成，再添加定位批注。');return}viewer?.annotate();toast('请点击模型表面，选择批注位置。')}else if(a==='locate-annotation'){const anno=p.annotations.find(x=>x.id===id);selectedFile=anno.fileId||'example';tab='model';pane='center';if(anno.fileId){const m=conversions.states.get(anno.fileId)||await conversions.inspect(anno.fileId);if(m&&anno.modelResultId)conversions.states.set(anno.fileId,{...m,status:'ready',resultId:anno.modelResultId,viewerUrl:'/api/models/'+anno.fileId+'/results/'+anno.modelResultId})}render();const el=$('#model-area');if(el)el._restoreCamera=anno.camera;toast(anno.text)}}catch(err){toast(err.message)}});
function showProjectDetails(){const p=current();showModal('项目背景与设计目标','说明任务边界，让材料和点评围绕同一个设计问题。',`<form id="project-form"><div class="form-field"><label>项目名称</label><input name="name" value="${esc(p.name)}" required maxlength="80"></div><div class="form-field"><label>任务背景</label><textarea name="description" required>${esc(p.description)}</textarea></div><div class="form-field"><label>设计目标</label><textarea name="goal">${esc(p.goal)}</textarea></div><div class="form-field"><label>目标使用者</label><input name="users" value="${esc(p.users)}"></div><div class="modal-actions"><button class="btn primary">保存项目资料</button></div></form>`)}
document.addEventListener('submit',async e=>{const form=e.target;if(!form.id)return;e.preventDefault();const data=Object.fromEntries(new FormData(form));if(Object.entries(data).some(([k,v])=>form.querySelector(`[name="${k}"]`)?.required&&!String(v).trim())){toast('必填内容不能只包含空格。');return}const submit=form.querySelector('[type=submit],button:not([type])');if(submit)submit.disabled=true;try{if(form.id.startsWith('board-')){await board.submit(form)}else if(form.id.startsWith('sp-')){await planner.submit(form)}else if(form.id.startsWith('dw-')){await designFlow.submit(form)}else if(form.id.startsWith('room-')){await rooms.submit(form)}else if(form.id==='material-meta-form'){await materials.saveMeta(form);closeModal()}else if(form.id==='pdf-pages-form'){await materials.savePages()}else if(form.id==='ai-followup-form'){await ai.sendFollowup(form)}else if(form.id==='ai-generate-form'){await ai.generate(form)}else if(form.id==='ai-connection-form'){await ai.saveConnection(form)}else if(form.id==='new-project-form'){const p=makeProject(data.name.trim(),data.description.trim(),state.projects.length%3,false);p.goal=data.goal;p.users=data.users;state.projects.unshift(p);projectId=p.id;selectedFile='';dirtyRevision++;await save();closeModal();location.hash='#/design/'+p.id;render();toast('项目已创建。上传材料，开始你的设计记录。')}else if(form.id==='project-form'){Object.assign(current(),data);changed();await save();closeModal();render();toast('项目资料已保存。')}else if(form.id==='course-form'){state.course=data;changed();await save();toast('课程任务已保存。')}else if(form.id==='response-form'){const p=state.projects.find(p=>p.id===form.dataset.project);const f=p.feedback.find(f=>f.id===form.dataset.id);if(f.response)f.history.push({...f.response,status:f.status});f.response={decision:data.decision,reason:data.reason.trim(),change:data.change,at:new Date().toISOString()};f.status=data.status;p.stage=Math.max(p.stage,4);changed();await save();closeModal();render();toast('回应已保存，设计判断已留下记录。')}else if(form.id==='snapshot-form'){await save();const r=await api('/api/snapshots',{method:'POST',headers:{'If-Match':etag},body:JSON.stringify({projectId:current().id,kind:form.dataset.kind,label:data.label,note:data.note})});state=r.state;etag=r.etag;closeModal();location.hash=form.dataset.kind==='defense'?'#/defense':'#/archive';render();toast('阶段快照已保存，后续修改不会影响此版本。')}else if(form.id==='question-form'){const p=current(),v=[...p.versions].reverse().find(v=>v.kind==='defense');let q=p.questions.find(q=>q.id===form.dataset.id);if(q){q.history=q.history||[];q.history.push({...q,history:undefined});Object.assign(q,data,{updatedAt:new Date().toISOString()})}else p.questions.push({id:crypto.randomUUID(),...data,versionId:v.id,versionNumber:v.number,at:new Date().toISOString(),role:'教师视图演示'});changed();await save();closeModal();render();toast('课堂记录已保存。')}else if(form.id==='annotation-form'){const pt=form._point;current().annotations.push({id:crypto.randomUUID(),text:data.text.trim(),position:pt.position,camera:pt.camera,...(form._binding||{modelVersion:'示例模型 V1'}),at:new Date().toISOString(),role:'教师视图演示'});changed();await save();feedbackSource='teacher';closeModal();render();toast('批注已保存，可恢复对应视角。')}}catch(err){toast('未能保存：'+err.message)}finally{if(submit)submit.disabled=false}});
document.addEventListener('change',e=>{if(e.target.matches('[data-component]')){viewTools.toggleComponent(e.target.dataset.component,e.target.checked)}if(e.target.matches('.model-compare-select'))viewTools.updateCompare();if(e.target.matches('.compare-select')){$('#compare-'+e.target.dataset.side).textContent=versionText(current().versions.find(v=>v.id===e.target.value))}});
document.addEventListener('keydown',e=>{const modal=$('.modal');if(e.key==='Escape'){if(modal)closeModal();$('.sidebar')?.classList.remove('open')}if(modal&&e.key==='Tab'){const els=[...modal.querySelectorAll('button,input,textarea,select,a[href],summary')].filter(x=>!x.disabled&&x.offsetParent!==null);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();save().then(()=>toast('已保存至云端。')).catch(err=>toast(err.message))}});
window.addEventListener('hashchange',()=>{rooms.onNavigate();closeModal();render();window.scrollTo(0,0)});window.addEventListener('beforeunload',e=>{if(dirtyRevision>savedRevision){e.preventDefault();e.returnValue=''}});window.addEventListener('online',()=>{if(dirtyRevision>savedRevision)save().then(()=>toast('网络已恢复，修改已保存。')).catch(e=>toast(e.message))});
init();

document.addEventListener('design-host-action',async e=>{const {action,id}=e.detail;try{if(action==='snapshot')snapshotModal('stage');else if(action==='room-create')await rooms.action('room-create',{});else if(action==='project-details')showProjectDetails();else if(action==='view-version'){const v=current().versions.find(v=>v.id===id);if(v)viewVersion(v)}}catch(error){toast(error.message)}});
